package com.example.orchestrator;
import java.util.*;
public final class WorkflowFactory {private WorkflowFactory(){}public static WorkflowGraph create(String scenario){WorkflowGraph g=new WorkflowGraph();g.add(n("requirements","requirements",Set.of(),false,0,false,c->{c.data().put("requirements",scenario);return NodeResult.ok("requirements captured");}));g.add(n("architecture","architecture",Set.of("requirements"),false,0,false,c->NodeResult.ok("architecture produced")));g.add(n("decompose","planning",Set.of("requirements","architecture"),false,0,false,c->NodeResult.ok("tasks decomposed")));g.add(n("implement","implementation",Set.of("decompose"),false,1,true,c->NodeResult.ok("Java implementation completed")));g.add(n("test","testing",Set.of("implement"),true,2,true,c->{c.data().put("testsPassed",true);return NodeResult.ok("tests passed");}));g.add(n("security","security",Set.of("implement"),true,1,false,c->{c.data().put("securityPassed",true);return NodeResult.ok("security review passed");}));g.add(n("docs","documentation",Set.of("implement"),true,0,false,c->NodeResult.ok("documentation synchronized")));g.add(n("release","release",Set.of("test","security","docs"),true,0,false,c->NodeResult.ok("release approved")));return g;}private static WorkflowNode n(String id,String role,Set<String>d,boolean approval,int retries,boolean comp,WorkflowNode.NodeAction action){return new WorkflowNode(id,role,d,true,approval,retries,comp,action);}}
